194		if !reflect.DeepEqual(res.CompartmentChanges, []CompartmentChange{
195			{CompartmentID: "C2", WeightBefore: 40, WeightAfter: 70},
196			{CompartmentID: "C3", WeightBefore: 30, WeightAfter: 0},
197		}) {
198			t.Fatalf("舱位重量变化应为 C2 增 30、C3 收 30，且不含 C1: %+v", res.CompartmentChanges)
199		}
200	
201		// 提交后按货物查询：G1 只在 C2，登记资料不变。
202		g1, _ = r.Cargo("G1")
203		if !g1.Loaded || g1.CompartmentID != "C2" ||
204			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
205			t.Fatalf("提交后 G1 应带着原登记资料只位于 C2: %+v", g1)
206		}
207		// 按舱位查看清单：C1、C3 清空，C2 含 G1、G2 共 70 千克、剩余 30 千克。
208		c1, _ = r.Compartment("C1")
209		if c1.UsedWeight != 0 || c1.RemainingWeight != 100 || len(c1.Cargo) != 0 {
210			t.Fatalf("提交后 C1 应保持清空、已用 0 剩余 100（不能再次扣减）: %+v", c1)
211		}
212		c2, _ := r.Compartment("C2")
213		if c2.UsedWeight != 70 || c2.RemainingWeight != 30 ||
214			!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
215			t.Fatalf("提交后 C2 应含 G1、G2 共 70 千克、剩余 30 千克: %+v", c2)
216		}
217		c3, _ = r.Compartment("C3")
218		if c3.UsedWeight != 0 || c3.RemainingWeight != 100 || len(c3.Cargo) != 0 {
219			t.Fatalf("提交后 C3 应已移除 G1、保持清空: %+v", c3)
220		}
221		// 其他货物保持原状，且货物查询与舱位清单一致。
222		g2, _ := r.Cargo("G2")
223		if !g2.Loaded || g2.CompartmentID != "C2" || g2.Weight != 40 {
224			t.Fatalf("G2 应保持原状留在 C2: %+v", g2)
225		}
226		for _, cv := range c2.Cargo {
227			cargo, _ := r.Cargo(cv.ID)
228			if !cv.Loaded || cv.CompartmentID != "C2" ||
229				cargo.CompartmentID != "C2" || cargo.Weight != cv.Weight {
230				t.Fatalf("舱位清单与货物查询对 %s 的记录不一致: 清单=%+v 查询=%+v", cv.ID, cv, cargo)
231			}
232		}
233	
234		// 已成功使用过的 A1 以原内容再次提交，只返回首次的历史结果
235		// （C1 到 C3），不按当前位置执行任何新移动：G1 必须仍在 C2。
236		again, err := r.Adjust("A1", []Op{{Kind: OpMove, CargoID: "G1", Target: "C3"}})
237		if err != nil {
238			t.Fatalf("A1 以原内容再次提交应返回首次结果: %v", err)
239		}
240		if !reflect.DeepEqual(again.CargoChanges, first.CargoChanges) ||
241			!reflect.DeepEqual(again.CompartmentChanges, first.CompartmentChanges) {
242			t.Fatalf("A1 再次提交应原样返回首次历史结果: again=%+v first=%+v", again, first)
243		}
244		g1, _ = r.Cargo("G1")
245		if !g1.Loaded || g1.CompartmentID != "C2" {
246			t.Fatalf("历史结果不能当成新移动执行，G1 应仍在 C2: %+v", g1)
247		}
248		c2, _ = r.Compartment("C2")
249		if c2.UsedWeight != 70 || !reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
250			t.Fatalf("历史结果返回后 C2 配载不应改变: %+v", c2)
251		}
252		c3, _ = r.Compartment("C3")
253		if c3.UsedWeight != 0 || len(c3.Cargo) != 0 {
254			t.Fatalf("历史结果返回后 C3 应仍清空: %+v", c3)
255		}
256	
257		// 后续移动与正式提交都不能改写保存下来的旧预览快照。
258		assertStaleMoveSnapshot(t, old)
259	}
