261	// TestStalePreviewSubmitAfterInterveningUnloadStateMismatch 保护不能移动的
262	// 情况之一：另一笔调整已把 G1 卸下，再提交原来的移动安排，必须返回现有
263	// 的“状态不符”错误并指出 G1，不能把移动变成重新装载；不返回成功调整
264	// 结果，错误携带本次提交编号 A2，配载保持另一笔调整完成后的状态。
265	func TestStalePreviewSubmitAfterInterveningUnloadStateMismatch(t *testing.T) {
266		r, ops, old := setupStaleMoveScenario(t)
267	
268		// 另一笔调整先把 G1 从 C1 卸下。
269		first := mustAdjust(t, r, "A1", []Op{{Kind: OpUnload, CargoID: "G1"}})
270		if !reflect.DeepEqual(first.CargoChanges, []CargoChange{{CargoID: "G1", From: "C1", To: ""}}) {
271			t.Fatalf("另一笔调整的货物变化应为 C1 卸下: %+v", first.CargoChanges)
272		}
273		if !reflect.DeepEqual(first.CompartmentChanges, []CompartmentChange{
274			{CompartmentID: "C1", WeightBefore: 30, WeightAfter: 0},
275		}) {
276			t.Fatalf("另一笔调整的舱位重量变化错误: %+v", first.CompartmentChanges)
277		}
278		g1, _ := r.Cargo("G1")
279		if g1.Loaded || g1.CompartmentID != "" {
280			t.Fatalf("另一笔调整后 G1 应已卸下、记录保留: %+v", g1)
281		}
282	
283		// 直接提交原移动安排：状态不符，不能当成重新装入 C2。
284		res, err := r.Adjust("A2", ops)
285		se := requireError(t, err, ErrStateMismatch)
286		if res != nil {
287			t.Fatalf("货物已卸下时必须拒绝移动，不应返回成功调整结果: %+v", res)
288		}
289		if se.ID != "G1" {
290			t.Fatalf("状态不符错误应指出货物 G1，实际 ID=%q", se.ID)
291		}
292		if se.AdjustmentID != "A2" {
293			t.Fatalf("错误应携带本次提交的调整编号 A2，实际 %q", se.AdjustmentID)
294		}
295		if msg := se.Error(); !strings.Contains(msg, "G1") {
296			t.Fatalf("状态不符说明应指出货物 G1: %s", msg)
297		}
298	
299		// 配载保留另一笔调整完成后的状态：G1 仍卸下，没有被装入 C2。
300		g1, _ = r.Cargo("G1")
301		if g1.Loaded || g1.CompartmentID != "" ||
302			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
303			t.Fatalf("拒绝后 G1 应保持已卸下且登记资料不变: %+v", g1)
304		}
305		c1, _ := r.Compartment("C1")
306		if c1.UsedWeight != 0 || len(c1.Cargo) != 0 {
307			t.Fatalf("拒绝后 C1 应保持清空: %+v", c1)
308		}
309		c2, _ := r.Compartment("C2")
310		if c2.UsedWeight != 40 || c2.RemainingWeight != 60 ||
311			!reflect.DeepEqual(cargoIDs(*c2), []string{"G2"}) {
312			t.Fatalf("拒绝后 C2 应仍只有 G2 一件 40/60，不能把 G1 装进来: %+v", c2)
313		}
314	
315		// 失败不占用编号：同一编号 A2 再次提交仍得到同样的状态不符，
316		// 而不是“调整编号冲突”，配载依旧不变。
317		res2, err2 := r.Adjust("A2", ops)
318		se2 := requireError(t, err2, ErrStateMismatch)
319		if res2 != nil {
320			t.Fatalf("失败的调整不应占用编号，也不应返回成功结果: %+v", res2)
321		}
322		if se2.ID != "G1" || se2.AdjustmentID != "A2" {
323			t.Fatalf("再次提交应仍为指出 G1、携带 A2 的状态不符: %+v", se2)
324		}
325		g1, _ = r.Cargo("G1")
326		if g1.Loaded || g1.CompartmentID != "" {
327			t.Fatalf("再次失败后 G1 应仍保持卸下: %+v", g1)
328		}
329	
330		// 卸下与失败提交都不能改写保存下来的旧预览快照。
331		assertStaleMoveSnapshot(t, old)
332	}
333	
334	// TestStalePreviewSubmitAfterAlreadyAtTargetDuplicate 保护不能移动的情况
335	// 之二：另一笔调整已把 G1 移到原清单的目标 C2，再提交原安排必须返回现有
336	// 的“重复操作”错误并指出 G1，不能当作一次成功移动，也不能重复占用重量；
337	// 不返回成功调整结果，错误携带本次提交编号 A2，配载保持另一笔调整完成后
338	// 的状态。
339	func TestStalePreviewSubmitAfterAlreadyAtTargetDuplicate(t *testing.T) {
340		r, ops, old := setupStaleMoveScenario(t)
341	
342		// 另一笔调整先把 G1 从 C1 移到原清单的目标 C2。
343		first := mustAdjust(t, r, "A1", []Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}})
344		if !reflect.DeepEqual(first.CargoChanges, []CargoChange{{CargoID: "G1", From: "C1", To: "C2"}}) {
345			t.Fatalf("另一笔调整的货物变化应为 C1 到 C2: %+v", first.CargoChanges)
346		}
347		if !reflect.DeepEqual(first.CompartmentChanges, []CompartmentChange{
348			{CompartmentID: "C1", WeightBefore: 30, WeightAfter: 0},
349			{CompartmentID: "C2", WeightBefore: 40, WeightAfter: 70},
350		}) {
351			t.Fatalf("另一笔调整的舱位重量变化错误: %+v", first.CompartmentChanges)
352		}
353	
354		// 再提交原移动安排：G1 已在目标舱位 C2，属于重复操作。
355		res, err := r.Adjust("A2", ops)
356		se := requireError(t, err, ErrDuplicateOp)
357		if res != nil {
358			t.Fatalf("货物已在目标舱位时必须拒绝，不应返回成功调整结果: %+v", res)
359		}
360		if se.ID != "G1" {
361			t.Fatalf("重复操作错误应指出货物 G1，实际 ID=%q", se.ID)
362		}
363		if se.AdjustmentID != "A2" {
364			t.Fatalf("错误应携带本次提交的调整编号 A2，实际 %q", se.AdjustmentID)
365		}
366		if msg := se.Error(); !strings.Contains(msg, "G1") || !strings.Contains(msg, "C2") {
367			t.Fatalf("重复操作说明应指出货物 G1 与目标舱位 C2: %s", msg)
368		}
369	
370		// 不能当作成功移动，也不能重复占用重量：G1 在 C2 清单中只出现一次，
371		// C2 已用仍为 70 千克；C1 保持清空。
372		g1, _ := r.Cargo("G1")
373		if !g1.Loaded || g1.CompartmentID != "C2" ||
374			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
375			t.Fatalf("拒绝后 G1 应仍只位于 C2、登记资料不变: %+v", g1)
376		}
377		c2, _ := r.Compartment("C2")
378		if c2.UsedWeight != 70 || c2.RemainingWeight != 30 ||
379			!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
380			t.Fatalf("拒绝后 C2 应仍只含 G1、G2 共 70 千克，重量不能重复占用: %+v", c2)
381		}
382		c1, _ := r.Compartment("C1")
383		if c1.UsedWeight != 0 || c1.RemainingWeight != 100 || len(c1.Cargo) != 0 {
384			t.Fatalf("拒绝后 C1 应保持清空: %+v", c1)
385		}
386		g2, _ := r.Cargo("G2")
387		if !g2.Loaded || g2.CompartmentID != "C2" || g2.Weight != 40 {
388			t.Fatalf("G2 应保持原状留在 C2: %+v", g2)
389		}
390	
391		// 失败不占用编号：同一编号 A2 再次提交仍得到同样的重复操作错误，
392		// 而不是“调整编号冲突”，重量仍不重复占用。
393		res2, err2 := r.Adjust("A2", ops)
394		se2 := requireError(t, err2, ErrDuplicateOp)
395		if res2 != nil {
396			t.Fatalf("失败的调整不应占用编号，也不应返回成功结果: %+v", res2)
397		}
398		if se2.ID != "G1" || se2.AdjustmentID != "A2" {
399			t.Fatalf("再次提交应仍为指出 G1、携带 A2 的重复操作: %+v", se2)
400		}
401		c2, _ = r.Compartment("C2")
402		if c2.UsedWeight != 70 || c2.RemainingWeight != 30 ||
403			!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
404			t.Fatalf("再次失败后 C2 重量与清单应保持不变: %+v", c2)
405		}
406	
407		// 移动与失败提交都不能改写保存下来的旧预览快照。
408		assertStaleMoveSnapshot(t, old)
409	}
410

